contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        require(true);
        // Setup: ensure the contract is not initialized yet.
        // The fresh deployment starts with intitalized = false, so SetMinSum is allowed once.

        // Make the deciding state-changing call.
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;

        // Read back the public state variable through its getter.
        uint readVal = c.MinSum(); if (__ESBMC_reverted()) return;

        // General rule: the setter stores exactly the provided value when uninitialized.
        assert(readVal == _val);
    }

    receive() external payable {}
}

